namespace NovaHarvest.Core.Quests; public sealed class QuestObjective { public string Id{get;}public string Description{get;}public int RequiredAmount{get;}public int CurrentAmount{get;private set;}public bool IsCompleted=>CurrentAmount>=RequiredAmount;public QuestObjective(string id,string description,int requiredAmount){Id=id;Description=description;RequiredAmount=Math.Max(1,requiredAmount);}public void AddProgress(int n){if(n>0)CurrentAmount=Math.Min(RequiredAmount,CurrentAmount+n);} }
